EXPLAIN ANALYZE SELECT s.id,s.source_channel,s.source_event_time,c.title,c.severity_level FROM t_feedback_source s JOIN t_feedback_content c ON c.source_id=s.id WHERE s.source_channel='SDK' AND s.source_event_time>=DATE_SUB(NOW(),INTERVAL 7 DAY) AND c.is_deleted=0 ORDER BY s.source_event_time DESC,s.id DESC LIMIT 50;
EXPLAIN ANALYZE SELECT s.id,c.title,c.function_module FROM t_feedback_source s JOIN t_feedback_content c ON c.source_id=s.id WHERE s.source_channel='QUALITY' AND s.province_code='SHANGHAI' AND c.function_module='AI_TUTOR' AND c.is_deleted=0 ORDER BY s.source_event_time DESC LIMIT 50;
EXPLAIN ANALYZE SELECT s.*,c.*,a.ai_summary,a.ai_category,a.ai_severity FROM t_feedback_source s JOIN t_feedback_content c ON c.source_id=s.id LEFT JOIN t_feedback_ai a ON a.source_id=s.id WHERE s.source_record_id='D10P-20260730A-SRC-000001';
EXPLAIN ANALYZE SELECT s.source_channel,COUNT(*) FROM t_feedback_source s JOIN t_feedback_content c ON c.source_id=s.id WHERE s.source_channel IN('SDK','JIRA','QUALITY','REDBLACK') AND c.severity_level IN('S0','S1') AND c.is_deleted=0 GROUP BY s.source_channel;
EXPLAIN ANALYZE SELECT DATE(s.source_event_time),s.source_channel,COUNT(*) FROM t_feedback_source s JOIN t_feedback_content c ON c.source_id=s.id WHERE s.source_event_time>=DATE_SUB(NOW(),INTERVAL 30 DAY) AND c.is_deleted=0 AND c.masking_status='PASS' GROUP BY DATE(s.source_event_time),s.source_channel ORDER BY DATE(s.source_event_time);
EXPLAIN ANALYZE SELECT l.cluster_id,COUNT(*) records,COUNT(DISTINCT s.source_channel) channels FROM t_cluster_link l JOIN t_feedback_source s ON s.id=l.feedback_source_id JOIN t_feedback_content c ON c.source_id=s.id WHERE l.cluster_id BETWEEN (SELECT MIN(id) FROM t_cluster WHERE cluster_name LIKE 'D10P-20260730A-CL-%') AND (SELECT MAX(id) FROM t_cluster WHERE cluster_name LIKE 'D10P-20260730A-CL-%') AND l.is_active=1 AND l.relation_role='MAIN' AND c.is_deleted=0 GROUP BY l.cluster_id ORDER BY records DESC LIMIT 50;
EXPLAIN ANALYZE SELECT id,batch_id FROM t_import_batch WHERE batch_status IN('MAPPING_CONFIRMED','PROCESSING') AND (lease_expires_at IS NULL OR lease_expires_at<NOW(3)) ORDER BY created_at LIMIT 10 FOR UPDATE SKIP LOCKED;
EXPLAIN ANALYZE SELECT id FROM t_sdk_ingest WHERE ingest_status IN('RECEIVED','RETRY_PENDING') AND (next_retry_at IS NULL OR next_retry_at<=NOW(3)) ORDER BY id LIMIT 10 FOR UPDATE SKIP LOCKED;
EXPLAIN ANALYZE SELECT i.id,i.instance_status,i.instance_severity,r.rule_code FROM t_alert_instance i JOIN t_alert_rule r ON r.id=i.rule_id WHERE i.instance_status IN('FIRING','ACKNOWLEDGED') ORDER BY i.fired_at DESC LIMIT 50;
EXPLAIN ANALYZE SELECT s.source_channel,c.function_module,c.severity_level,COUNT(*) FROM t_feedback_source s JOIN t_feedback_content c ON c.source_id=s.id WHERE s.source_event_time>=DATE_SUB(NOW(),INTERVAL 30 DAY) AND s.source_channel IN('SDK','JIRA') AND c.is_deleted=0 AND c.masking_status='PASS' GROUP BY s.source_channel,c.function_module,c.severity_level;
